// Module work queues only. This does not produce runtime cards or approve any content.
const fs = require('fs'), path = require('path');
const { loadBody } = require('./lib/notes-learning-compiler');
const { hash } = require('../miniprogram/subpackages/note/services/memory-content');
const root = path.resolve(__dirname, '..');
const read = rel => JSON.parse(fs.readFileSync(path.join(root, rel), 'utf8'));
const audit = read('docs/knowledge-platform/content/notes/memory-v5-audit.json');
const samples = read('docs/knowledge-platform/content/notes/memory-v5-samples.json');
const closure = read('docs/knowledge-platform/implementations/evidence/notes-memory-v5-p3-definition-close-20261022.json');
if (closure.status !== 'definition-closed-with-local-deferrals' || closure.formalContentApproved !== 0) throw Error('定义收口和内容准入必须分开');
const draftPath='docs/knowledge-platform/content/notes/memory-v5-da01-drafts.json';
const drafts=fs.existsSync(path.join(root,draftPath))?read(draftPath).cards:[];
const body = loadBody(root), keys = new Set();
const order = [['DA','data-analysis','资料分析'],['QU','quantity','数量关系'],['LO','logic','判断推理'],['VE','verbal','言语理解'],['GR','graphic','图形推理']];
const modules = order.map(([code,id,title], index) => {
  const sources = audit.sources.filter(s => s.primaryModuleId === id).map(s => {
    const ref = s.sourceIdentity, key = ref.subjectId + ':' + ref.pointId;
    if (keys.has(key)) throw Error('重复来源'); keys.add(key);
    const point = body[ref.subjectId]?.points.find(p => p.id === ref.pointId), tab = point?.tabs.find(t => t.id === s.tabId);
    if (!point || hash(point) !== s.sourceSha256 || !tab || hash(tab) !== s.tabSha256 || tab.blocks.length !== s.blocks.length) throw Error('来源审计过期：' + key);
    for (const block of s.blocks) if (hash(tab.blocks[block.blockIndex]) !== block.sha256) throw Error('原块审计过期：' + key);
    const designDrafts=drafts.filter(c=>c.workUnitId===`memory-expansion-${code.toLowerCase()}-${ref.subjectId}-${ref.pointId}`);
    const pilotCardIds = samples.cards.filter(c => c.refs.some(r => r.subjectId === ref.subjectId && r.pointId === ref.pointId)).map(c => c.id);
    return { workUnitId: `memory-expansion-${code.toLowerCase()}-${ref.subjectId}-${ref.pointId}`, sourceIdentity: ref,
      title: s.title, categoryId: point.categoryId, primaryModuleId: id, originalSubjectId: ref.subjectId,
      sourceSha256: s.sourceSha256, tabId: s.tabId, tabSha256: s.tabSha256,
      originalBlocks: s.blocks.map(b => ({ blockIndex: b.blockIndex, type: b.type, expectedBlockSha256: b.sha256, requiredContext: b.requiredContext })),
      existingPilotCardIds: pilotCardIds, designDraftIds:designDrafts.map(c=>c.id), localDraftHolds:designDrafts.filter(c=>c.localHold).map(c=>({cardId:c.id,...c.localHold})), sourceObservations: s.sourceHolds,
      stage: s.sourceHolds.length ? 'source-observation-triage' : designDrafts.some(c=>c.localHold)?'local-draft-hold':designDrafts.length?'design-draft-prepared':pilotCardIds.length ? 'reuse-existing-pilot-and-check-target-gaps' : 'single-source-composition-design',
      requiresSharedOwnershipEvidence: ref.subjectId !== id,
      provisionalKindHint: id === 'graphic' ? 'method' : s.recomposition.suggestedKind,
      kindHintIsAdmission: false, finalCardCount: null, independentReview: 'not-created', formalApproved: false };
  });
  return { batchId: `ME-${code}`, order: index + 1, moduleId: id, title, sourceCount: sources.length,
    sourceBlockCount: sources.reduce((n,s) => n+s.originalBlocks.length,0),
    sourcesWithObservations: sources.filter(s => s.sourceObservations.length).length,
    observationCount: sources.reduce((n,s) => n+s.sourceObservations.length,0),
    existingPilotCardIds: [...new Set(sources.flatMap(s => s.existingPilotCardIds))], sources,
    exitRule: 'Every source classified, exact selectors and necessary context recorded for proposed combinations, duplicates and local holds explicit; actual card count determined from meaningful targets, not source/row counts. Development preview, independent review, device and release remain distinct.' };
});
if (keys.size !== 162 || modules.reduce((n,m)=>n+m.sourceBlockCount,0)!==686) throw Error('来源范围改变');
const first = modules[0];
const firstDesign = first.sources.filter(s => !s.sourceObservations.length && !s.existingPilotCardIds.length && !s.requiresSharedOwnershipEvidence);
const plan = { schemaVersion:1,date:'2026-10-22',version:'notes-memory-expansion-plan-v1',scope:'Planning and source preflight, not generated cards or content approval',productDefinition:closure.status,
  formalApproved:0,newRuntimeCards:0,designDraftCards:drafts.length,localDraftHolds:drafts.filter(c=>c.localHold).length,sourceCount:keys.size,sourceBlockCount:686,sourceObservationCount:audit.sourceHolds,
  sourceCountsAreNotCardTargets:true,modules,
  firstSubBatch:{batchId:'ME-DA-01',purpose:'Reuse two existing DA pilots and design original-reference combinations from remaining sources without recorded observations first',
    alreadyPilotCardIds:first.existingPilotCardIds,
    initialDesignWorkUnits:firstDesign.map(s=>s.workUnitId),initialDesignSourceCount:firstDesign.length,
    observationTriageWorkUnits:first.sources.filter(s=>s.sourceObservations.length).map(s=>s.workUnitId),
    sourceWithoutObservationsIsNotApproved:true,newCardCount:null,designDraftIds:drafts.map(c=>c.id),state:drafts.length?'original-reference design drafts delivered; no runtime enrollment or independent acceptance':'source-preflight-delivered; no new cards generated'},
  preserved:{original50Json:true,originalFormulaEngine:true,oldQuestionHistory:true,old22Drafts:true,old3ApplicationHolds:true},
  productEscalation:'Only unresolved product choices or required account/device actions need the user; routine referencing, duplicate checks, planning and development drafting proceed automatically. Exact content review remains independent before formal admission.' };
const dest=path.join(root,'docs/knowledge-platform/implementations/notes-memory-v5-expansion-plan-v1.json'),output=JSON.stringify(plan,null,2)+'\n';
if(process.argv.includes('--check-only')){if(fs.readFileSync(dest,'utf8')!==output)throw Error('扩充批次清单过期');}else fs.writeFileSync(dest,output);
console.log(JSON.stringify({passed:true,modules:modules.length,sourceCount:keys.size,sourceBlockCount:686,firstDesignSources:firstDesign.length,pilotCardsReused:first.existingPilotCardIds.length,newRuntimeCards:0,designDraftCards:drafts.length,formalApproved:0,checkOnly:process.argv.includes('--check-only')}));

const assert=require('assert/strict'),fs=require('fs'),path=require('path');
const {loadBody}=require('./lib/notes-learning-compiler');
const {resolveCard,availableCards}=require('../miniprogram/subpackages/note/services/memory-content');
const root=path.resolve(__dirname,'..'),read=rel=>JSON.parse(fs.readFileSync(path.join(root,rel),'utf8'));
const plan=read('docs/knowledge-platform/implementations/notes-memory-v5-expansion-plan-v1.json'),drafts=read('docs/knowledge-platform/content/notes/memory-v5-da01-drafts.json');
const body=loadBody(root),pack=require('../miniprogram/subpackages/note/models/memory-pack'),current=availableCards(body,pack,true);
const allowed=new Set(plan.firstSubBatch.initialDesignWorkUnits),ids=new Set();
assert.equal(drafts.formalApproved,0);assert.equal(drafts.newRuntimeCards,0);assert.equal(drafts.cards.length,allowed.size);
for(const c of drafts.cards){
 assert(allowed.has(c.workUnitId));assert(!ids.has(c.id));ids.add(c.id);
 assert.equal(c.status,'draft');assert.equal(c.admission,'not-enrolled');assert.equal(c.formalApproved,false);assert.equal(c.semanticReview,'not-independently-approved');
 assert(!current.some(old=>old.id===c.id));const resolved=resolveCard(c,body);
 assert(resolved.blocks.length>0);assert(!resolved.blocks.some(b=>b.type==='example'||b.type==='practice'));
 if(c.pointId==='period-terms')assert(c.localHold&&c.localHold.affectedRef.blockIndex===0);
}
assert.equal(drafts.localHoldCount,drafts.cards.filter(c=>c.localHold).length);
assert.equal(availableCards(body,{schemaVersion:1,sampleOnly:true,cards:drafts.cards},true).length,0);
assert.equal(availableCards(body,pack,false).length,0);assert.equal(current.length,8);
console.log(JSON.stringify({passed:true,designDrafts:drafts.cards.length,localHolds:drafts.localHoldCount,runtimeCardsUnchanged:current.length,formalApproved:0,scope:'Exact source resolution, authoring boundary and non-admission; not independent semantic acceptance'}));
